#!/usr/bin/env python3
"""Active Satellites in Earth Orbit — 2026 Catalog Analysis Report Generator."""

import pandas as pd
import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
import matplotlib.ticker as mticker
from matplotlib.patches import FancyBboxPatch
import base64
from io import BytesIO
from collections import Counter
import json
import warnings
warnings.filterwarnings('ignore')

# ── Style ──────────────────────────────────────────────────────────
plt.rcParams.update({
    'font.family': 'DejaVu Sans',
    'font.size': 12,
    'axes.titlesize': 15,
    'axes.labelsize': 13,
    'axes.edgecolor': '#cccccc',
    'axes.grid': True,
    'grid.alpha': 0.4,
    'grid.color': '#dddddd',
    'figure.facecolor': 'white',
    'axes.facecolor': 'white',
})

PALETTE = {
    'navy':   '#1B2A4A',
    'blue':   '#2E6EB5',
    'teal':   '#1A8A8A',
    'orange': '#E07233',
    'red':    '#C0392B',
    'green':  '#27AE60',
    'gray':   '#7F8C8D',
    'light':  '#ECF0F1',
}

def fig_to_b64(fig):
    buf = BytesIO()
    fig.savefig(buf, format='png', dpi=150, bbox_inches='tight', facecolor='white')
    buf.seek(0)
    b64 = base64.b64encode(buf.read()).decode()
    plt.close(fig)
    return b64

def svg_fig_to_tag(fig, width='100%'):
    buf = BytesIO()
    fig.savefig(buf, format='svg', bbox_inches='tight', facecolor='white')
    buf.seek(0)
    svg = buf.read().decode()
    plt.close(fig)
    return svg

# ── Data Loading ───────────────────────────────────────────────────
print("Loading data...")
df = pd.read_csv('/app/benchmark/data.csv')

# Parse ECCENTRICITY from string to float
df['ECC'] = pd.to_numeric(df['ECCENTRICITY'], errors='coerce')

# Extract launch year from OBJECT_ID
df['LAUNCH_YEAR'] = df['OBJECT_ID'].str[:4].astype(int)

# Parse EPOCH
df['EPOCH_DT'] = pd.to_datetime(df['EPOCH'], errors='coerce')

# Extract constellation prefix from OBJECT_NAME
def get_constellation(name):
    if not isinstance(name, str):
        return 'Other'
    name_upper = name.upper().strip()
    prefixes = [
        ('STARLINK', 'Starlink'),
        ('ONEWEB', 'OneWeb'),
        ('GPS', 'GPS'),
        ('IRIDIUM', 'Iridium'),
        ('GLOBALSTAR', 'Globalstar'),
        ('ORBCOMM', 'Orbcomm'),
        ('BEIDOU', 'BeiDou'),
        ('GLONASS', 'GLONASS'),
        ('GALILEO', 'Galileo'),
        ('YAOGAN', 'Yaogan'),
        ('INTELSAT', 'Intelsat'),
        ('SES', 'SES'),
        ('EUTELSAT', 'Eutelsat'),
        ('INMARSAT', 'Inmarsat'),
        ('TDRS', 'TDRS'),
        ('FLOCK', 'Flock'),
        ('LEMUR', 'Lemur'),
        ('SPACEBEE', 'SpaceBee'),
        ('HAWK', 'Hawk'),
        ('ICEYE', 'ICEYE'),
        ('CAPELLA', 'Capella'),
        ('SKYSAT', 'SkySat'),
        ('WORLDVIEW', 'WorldView'),
        ('GAOFEN', 'Gaofen'),
    ]
    for prefix, label in prefixes:
        if name_upper.startswith(prefix):
            return label
    return 'Other'

df['CONSTELLATION'] = df['OBJECT_NAME'].apply(get_constellation)

# Orbit regime classification
def classify_orbit(mm, ecc):
    if pd.isna(mm):
        return 'Unknown'
    if mm > 14.0:
        return 'LEO'
    elif mm >= 6.0:
        return 'MEO'
    elif mm >= 0.8:
        if ecc > 0.25:
            return 'HEO'
        return 'GEO'
    else:
        return 'HEO'

df['ORBIT_REGIME'] = df.apply(lambda r: classify_orbit(r['MEAN_MOTION'], r['ECC']), axis=1)

# ── KPI Computation ────────────────────────────────────────────────
print("Computing KPIs...")
total = len(df)
leo_count = (df['ORBIT_REGIME'] == 'LEO').sum()
leo_share = round(leo_count / total * 100, 1)
starlink_count = (df['CONSTELLATION'] == 'Starlink').sum()
median_inc = round(df['INCLINATION'].median(), 1)
post_2020 = (df['LAUNCH_YEAR'] >= 2020).sum()
epoch_min = df['EPOCH_DT'].min().strftime('%Y-%m-%d')
epoch_max = df['EPOCH_DT'].max().strftime('%Y-%m-%d')

# Additional stats
meo_count = (df['ORBIT_REGIME'] == 'MEO').sum()
geo_count = (df['ORBIT_REGIME'] == 'GEO').sum()
heo_count = (df['ORBIT_REGIME'] == 'HEO').sum()
mean_inclination = round(df['INCLINATION'].mean(), 1)
mean_ecc = df['ECC'].mean()
median_ecc = df['ECC'].median()
mean_mm = round(df['MEAN_MOTION'].mean(), 2)

print(f"  Total: {total}")
print(f"  LEO: {leo_count} ({leo_share}%)")
print(f"  Starlink: {starlink_count}")
print(f"  Median inclination: {median_inc}°")
print(f"  Post-2020: {post_2020}")
print(f"  Epoch range: {epoch_min} to {epoch_max}")

# ── Chart Generation ───────────────────────────────────────────────
print("Generating charts...")

# Chart 1: Orbit Regime Distribution (pie)
fig1, ax1 = plt.subplots(figsize=(7, 6))
regime_counts = df['ORBIT_REGIME'].value_counts()
colors_regime = [PALETTE['blue'], PALETTE['teal'], PALETTE['orange'], PALETTE['gray']]
wedges, texts, autotexts = ax1.pie(
    regime_counts.values, labels=None,
    autopct='%1.1f%%', startangle=90,
    colors=colors_regime[:len(regime_counts)],
    pctdistance=0.75, explode=(0.03, 0.03, 0.03, 0.03)
)
for at in autotexts:
    at.set_fontsize(11)
    at.set_fontweight('bold')
ax1.legend(
    [f'{lbl}: {cnt:,}' for lbl, cnt in zip(regime_counts.index, regime_counts.values)],
    loc='lower center', ncol=2, frameon=False, fontsize=10
)
ax1.set_title('Active Satellites by Orbital Regime', fontweight='bold', color=PALETTE['navy'], pad=20)
chart1_b64 = fig_to_b64(fig1)

# Chart 2: Constellation Breakdown (horizontal bar, top 12)
fig2, ax2 = plt.subplots(figsize=(9, 5.5))
const_counts = df['CONSTELLATION'].value_counts()
top12 = const_counts.head(12)
others_sum = const_counts[12:].sum()
plot_data = pd.concat([top12, pd.Series({'Other': others_sum})])
colors_bar = [PALETTE['blue'] if i > 0 else PALETTE['orange'] for i in range(len(plot_data))]
bars = ax2.barh(range(len(plot_data)), plot_data.values, color=colors_bar, edgecolor='white', height=0.7)
ax2.set_yticks(range(len(plot_data)))
ax2.set_yticklabels(plot_data.index, fontsize=10)
ax2.set_xlabel('Number of Active Satellites', fontweight='bold')
ax2.set_title('Top Constellations & Operators', fontweight='bold', color=PALETTE['navy'])
ax2.invert_yaxis()
for bar, val in zip(bars, plot_data.values):
    ax2.text(bar.get_width() + 50, bar.get_y() + bar.get_height()/2,
             f'{val:,}', va='center', fontsize=10, fontweight='bold', color=PALETTE['navy'])
ax2.set_xlim(0, plot_data.values.max() * 1.18)
chart2_b64 = fig_to_b64(fig2)

# Chart 3: Launch Year Trends (bar chart by year)
fig3, ax3 = plt.subplots(figsize=(11, 5.5))
launch_years = df[df['LAUNCH_YEAR'] >= 1990]['LAUNCH_YEAR'].value_counts().sort_index()
ax3.bar(launch_years.index.astype(str), launch_years.values,
        color=PALETTE['blue'], edgecolor='white', width=0.75)
ax3.set_xlabel('Launch Year', fontweight='bold')
ax3.set_ylabel('Active Satellites', fontweight='bold')
ax3.set_title('Currently Active Satellites by Launch Year', fontweight='bold', color=PALETTE['navy'])
ax3.tick_params(axis='x', rotation=45, labelsize=8)
# Annotate key years
for yr in [2020, 2021, 2022, 2023, 2024, 2025]:
    if yr in launch_years.index:
        val = launch_years[yr]
        ax3.annotate(f'{val:,}', (str(yr), val), textcoords="offset points",
                    xytext=(0, 8), ha='center', fontsize=9, fontweight='bold', color=PALETTE['orange'])
ax3.set_ylim(0, launch_years.values.max() * 1.12)
chart3_b64 = fig_to_b64(fig3)

# Chart 3b: Cumulative launches
fig3b, ax3b = plt.subplots(figsize=(11, 5))
launch_years_full = df[df['LAUNCH_YEAR'] >= 1990]['LAUNCH_YEAR'].value_counts().sort_index()
cumulative = launch_years_full.cumsum()
ax3b.fill_between(range(len(cumulative)), cumulative.values, alpha=0.3, color=PALETTE['blue'])
ax3b.plot(range(len(cumulative)), cumulative.values, color=PALETTE['blue'], linewidth=2.5)
ax3b.set_xticks(range(0, len(cumulative), max(1, len(cumulative)//12)))
ax3b.set_xticklabels(cumulative.index[::max(1, len(cumulative)//12)], rotation=45, fontsize=9)
ax3b.set_ylabel('Cumulative Active Satellites', fontweight='bold')
ax3b.set_title('Cumulative Growth of Active Satellite Fleet (1990–Present)', fontweight='bold', color=PALETTE['navy'])
ax3b.yaxis.set_major_formatter(mticker.FuncFormatter(lambda x, p: f'{int(x):,}'))
chart3b_b64 = fig_to_b64(fig3b)

# Chart 4: Inclination Distribution (histogram)
fig4, ax4 = plt.subplots(figsize=(10, 5))
ax4.hist(df['INCLINATION'].dropna(), bins=60, color=PALETTE['blue'], edgecolor='white', alpha=0.85)
ax4.axvline(median_inc, color=PALETTE['orange'], linewidth=2.5, linestyle='--',
            label=f'Median: {median_inc}°')
# Annotate key inclinations
for deg, label, ypos in [(0, 'Equatorial\n(0°)', 0.85), (90, 'Polar\n(90°)', 0.85), (53, 'Starlink\n(~53°)', 0.65)]:
    ax4.axvline(deg, color=PALETTE['red'], linewidth=1, linestyle=':', alpha=0.6)
    ax4.text(deg + 0.5, ax4.get_ylim()[1] * ypos if ypos else 100, label,
             fontsize=8, color=PALETTE['red'], alpha=0.8)
ax4.set_xlabel('Inclination (degrees)', fontweight='bold')
ax4.set_ylabel('Satellite Count', fontweight='bold')
ax4.set_title('Distribution of Orbital Inclinations', fontweight='bold', color=PALETTE['navy'])
ax4.legend(frameon=False, fontsize=11)
chart4_b64 = fig_to_b64(fig4)

# Chart 5: Inclination by regime (box plot)
fig5, ax5 = plt.subplots(figsize=(8, 5.5))
regime_order = ['LEO', 'MEO', 'GEO', 'HEO']
data_box = [df[df['ORBIT_REGIME'] == r]['INCLINATION'].dropna().values for r in regime_order]
bp = ax5.boxplot(data_box, labels=regime_order, patch_artist=True, widths=0.5)
colors_box = [PALETTE['blue'], PALETTE['teal'], PALETTE['orange'], PALETTE['gray']]
for patch, color in zip(bp['boxes'], colors_box):
    patch.set_facecolor(color)
    patch.set_alpha(0.7)
ax5.set_ylabel('Inclination (degrees)', fontweight='bold')
ax5.set_title('Inclination Distribution by Orbital Regime', fontweight='bold', color=PALETTE['navy'])
chart5_b64 = fig_to_b64(fig5)

# Chart 6: Eccentricity distribution
fig6, ax6 = plt.subplots(figsize=(10, 5))
ecc_data = df['ECC'].dropna()
# Split into low-ecc and high-ecc for dual view
low_ecc = ecc_data[ecc_data < 0.1]
high_ecc = ecc_data[ecc_data >= 0.1]
ax6.hist(low_ecc, bins=50, color=PALETTE['blue'], edgecolor='white', alpha=0.85, label=f'Low ecc (<0.1): {len(low_ecc):,}')
ax6.axvline(ecc_data.median(), color=PALETTE['orange'], linewidth=2, linestyle='--',
            label=f'Median: {ecc_data.median():.4f}')
ax6.set_xlabel('Eccentricity', fontweight='bold')
ax6.set_ylabel('Satellite Count', fontweight='bold')
ax6.set_title('Distribution of Orbital Eccentricity (Low-Eccentricity Detail)', fontweight='bold', color=PALETTE['navy'])
ax6.legend(frameon=False, fontsize=10)
chart6_b64 = fig_to_b64(fig6)

# Chart 7: Starlink vs Non-Starlink comparison
fig7, (ax7a, ax7b) = plt.subplots(1, 2, figsize=(12, 5))
# Pie: Starlink share
starlink_share = [starlink_count, total - starlink_count]
ax7a.pie(starlink_share, labels=['Starlink', 'All Others'], autopct='%1.1f%%',
         startangle=90, colors=[PALETTE['orange'], PALETTE['light']],
         explode=(0.05, 0), textprops={'fontsize': 12, 'fontweight': 'bold'})
ax7a.set_title('Starlink Share of All Active Satellites', fontweight='bold', color=PALETTE['navy'])
# Bar: Regime distribution with/without Starlink
regime_all = df['ORBIT_REGIME'].value_counts()
regime_nosl = df[df['CONSTELLATION'] != 'Starlink']['ORBIT_REGIME'].value_counts()
x = np.arange(len(regime_order))
w = 0.35
ax7b.bar(x - w/2, [regime_all.get(r, 0) for r in regime_order], w,
         label='All Satellites', color=PALETTE['blue'], edgecolor='white')
ax7b.bar(x + w/2, [regime_nosl.get(r, 0) for r in regime_order], w,
         label='Excluding Starlink', color=PALETTE['orange'], edgecolor='white')
ax7b.set_xticks(x)
ax7b.set_xticklabels(regime_order)
ax7b.set_ylabel('Satellite Count', fontweight='bold')
ax7b.set_title('Orbital Regime: With vs Without Starlink', fontweight='bold', color=PALETTE['navy'])
ax7b.legend(frameon=False, fontsize=10)
ax7b.yaxis.set_major_formatter(mticker.FuncFormatter(lambda x, p: f'{int(x):,}'))
chart7_b64 = fig_to_b64(fig7)

# Chart 8: Launch rate acceleration (post-2015 monthly trend approximation by year)
fig8, ax8 = plt.subplots(figsize=(11, 5))
recent = df[df['LAUNCH_YEAR'] >= 2015]['LAUNCH_YEAR'].value_counts().sort_index()
bars8 = ax8.bar(recent.index.astype(str), recent.values,
                color=[PALETTE['blue'] if y < 2020 else PALETTE['orange'] for y in recent.index],
                edgecolor='white', width=0.7)
ax8.set_xlabel('Launch Year', fontweight='bold')
ax8.set_ylabel('Active Satellites', fontweight='bold')
ax8.set_title('Launch Activity Acceleration (2015–2025)', fontweight='bold', color=PALETTE['navy'])
for bar, val in zip(bars8, recent.values):
    ax8.text(bar.get_x() + bar.get_width()/2, bar.get_height() + 50,
             f'{val:,}', ha='center', fontsize=9, fontweight='bold', color=PALETTE['navy'])
ax8.set_ylim(0, recent.values.max() * 1.15)
ax8.axvspan(-0.5, 4.5, alpha=0.05, color='gray')
ax8.text(2, recent.values.max() * 1.08, 'Pre-2020', ha='center', fontsize=9,
         color=PALETTE['gray'], fontstyle='italic')
ax8.text(7, recent.values.max() * 1.08, 'Post-2020', ha='center', fontsize=9,
         color=PALETTE['orange'], fontstyle='italic')
chart8_b64 = fig_to_b64(fig8)

# Chart 9: Top operators excluding Starlink (to show diversity)
fig9, ax9 = plt.subplots(figsize=(9, 5))
non_sl = df[df['CONSTELLATION'] != 'Starlink']['CONSTELLATION'].value_counts()
top10_nosl = non_sl.head(10)
bars9 = ax9.barh(range(len(top10_nosl)), top10_nosl.values,
                 color=[PALETTE['teal'] if i > 0 else PALETTE['blue'] for i in range(len(top10_nosl))],
                 edgecolor='white', height=0.7)
ax9.set_yticks(range(len(top10_nosl)))
ax9.set_yticklabels(top10_nosl.index, fontsize=10)
ax9.set_xlabel('Number of Active Satellites', fontweight='bold')
ax9.set_title('Top Operators (Excluding Starlink)', fontweight='bold', color=PALETTE['navy'])
ax9.invert_yaxis()
for bar, val in zip(bars9, top10_nosl.values):
    ax9.text(bar.get_width() + 2, bar.get_y() + bar.get_height()/2,
             f'{val:,}', va='center', fontsize=10, fontweight='bold', color=PALETTE['navy'])
ax9.set_xlim(0, top10_nosl.values.max() * 1.2)
chart9_b64 = fig_to_b64(fig9)

# ── Additional Stats ──────────────────────────────────────────────
print("Computing additional statistics...")
# Pre/post 2020 comparison
pre2020 = (df['LAUNCH_YEAR'] < 2020).sum()
pre2020_pct = round(pre2020 / total * 100, 1)
post2020_pct = round(post_2020 / total * 100, 1)

# Inclination stats
inc_std = round(df['INCLINATION'].std(), 1)
inc_q1 = round(df['INCLINATION'].quantile(0.25), 1)
inc_q3 = round(df['INCLINATION'].quantile(0.75), 1)

# Eccentricity stats
high_ecc_count = (df['ECC'] > 0.1).sum()
high_ecc_pct = round(high_ecc_count / total * 100, 1)

# Starlink stats
sl_pct = round(starlink_count / total * 100, 1)
sl_leo = ((df['CONSTELLATION'] == 'Starlink') & (df['ORBIT_REGIME'] == 'LEO')).sum()
sl_median_mm = round(df[df['CONSTELLATION'] == 'Starlink']['MEAN_MOTION'].median(), 2)
sl_median_inc = round(df[df['CONSTELLATION'] == 'Starlink']['INCLINATION'].median(), 1)

# Without Starlink stats
