# Extract constellation prefix from OBJECT_NAME
def get_constellation(name):
    if not isinstance(name, str):
        return 'Other'
    name_upper = name.upper().strip()
    prefixes = [
        ('STARLINK', 'Starlink'),
        ('ONEWEB', 'OneWeb'),
        ('GPS', 'GPS'),
        ('IRIDIUM', 'Iridium'),
        ('GLOBALSTAR', 'Globalstar'),
        ('ORBCOMM', 'Orbcomm'),
        ('BEIDOU', 'BeiDou'),
        ('GLONASS', 'GLONASS'),
        ('GALILEO', 'Galileo'),
        ('YAOGAN', 'Yaogan'),
        ('INTELSAT', 'Intelsat'),
        ('SES', 'SES'),
        ('EUTELSAT', 'Eutelsat'),
        ('INMARSAT', 'Inmarsat'),
        ('TDRS', 'TDRS'),
        ('FLOCK', 'Flock'),
        ('LEMUR', 'Lemur'),
        ('SPACEBEE', 'SpaceBee'),
        ('HAWK', 'Hawk'),
        ('ICEYE', 'ICEYE'),
        ('CAPELLA', 'Capella'),
        ('SKYSAT', 'SkySat'),
        ('WORLDVIEW', 'WorldView'),
        ('GAOFEN', 'Gaofen'),
    ]
    for prefix, label in prefixes:
        if name_upper.startswith(prefix):
            return label
    return 'Other'

df['CONSTELLATION'] = df['OBJECT_NAME'].apply(get_constellation)

# Orbit regime classification
def classify_orbit(mm, ecc):
    if pd.isna(mm):
        return 'Unknown'
    if mm > 14.0:
        return 'LEO'
    elif mm >= 6.0:
        return 'MEO'
    elif mm >= 0.8:
        if ecc > 0.25:
            return 'HEO'
        return 'GEO'
    else:
        return 'HEO'

df['ORBIT_REGIME'] = df.apply(lambda r: classify_orbit(r['MEAN_MOTION'], r['ECC']), axis=1)

